import wandb, json
api = wandb.Api()

# Factorial run
run = api.run('xiaoyucorynne-/cost-verify-agent-rl/6liw7fm1')
hist = run.history(samples=500, pandas=False)

# Get val keys
val_keys = set()
train_keys = set()
for row in hist:
    for k in row.keys():
        if 'val' in k.lower() and ('success' in k.lower() or 'action' in k.lower() or 'pass' in k.lower()):
            val_keys.add(k)
        if 'train' in k.lower() and ('success' in k.lower() or 'action' in k.lower() or 'pass' in k.lower()):
            train_keys.add(k)

print('Val keys:', sorted(val_keys))
print('Train keys:', sorted(train_keys))

# Extract step-by-step data
metrics_to_get = [
    'train/AlfworldSG/success', 'train/AlfworldSG/pass@8', 
    'train/AlfworldSG/action_is_valid', 'train/AlfworldSG/manager_invalid_action',
    'actor/entropy', 'actor/kl_loss', 'actor/grad_norm',
]
results = []
for row in hist:
    step = row.get('_step')
    data = {'step': step}
    for m in metrics_to_get:
        if m in row and row[m] is not None:
            data[m] = row[m]
    # Val metrics
    for k in row:
        if k.startswith('val') and row[k] is not None and ('success' in k.lower() or 'action' in k.lower()):
            data[k] = row[k]
    if len(data) > 1:
        results.append(data)

print(f'\nTotal rows with data: {len(results)}')
for r in results:
    print(json.dumps(r, default=str))
" 2>&1 | grep -v "^wandb:"

